glsl3.vert:
precision highp float;
layout(std140) uniform CCGlobal {
  highp   vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_nativeSize;
  mediump vec4 cc_probeInfo;
  mediump vec4 cc_debug_view_mode;
};
layout(std140) uniform CCCamera {
  highp   mat4 cc_matView;
  highp   mat4 cc_matViewInv;
  highp   mat4 cc_matProj;
  highp   mat4 cc_matProjInv;
  highp   mat4 cc_matViewProj;
  highp   mat4 cc_matViewProjInv;
  highp   vec4 cc_cameraPos;
  mediump vec4 cc_surfaceTransform;
  mediump vec4 cc_screenScale;
  mediump vec4 cc_exposure;
  mediump vec4 cc_mainLitDir;
  mediump vec4 cc_mainLitColor;
  mediump vec4 cc_ambientSky;
  mediump vec4 cc_ambientGround;
  mediump vec4 cc_fogColor;
  mediump vec4 cc_fogBase;
  mediump vec4 cc_fogAdd;
  mediump vec4 cc_nearFar;
  mediump vec4 cc_viewPort;
};
in vec3 a_position;
in vec2 a_texCoord;
out vec2 v_uv;
out vec2 v_screen;
vec4 vert () {
  v_uv = a_texCoord;
  v_screen = a_position.xy + 0.5;
  return vec4(a_position.xy * 2.0, 0.99999, 1.0);
}
void main() { gl_Position = vert(); }

glsl3.frag:
precision highp float;
layout(std140) uniform CCGlobal {
  highp   vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_nativeSize;
  mediump vec4 cc_probeInfo;
  mediump vec4 cc_debug_view_mode;
};
layout(std140) uniform CCCamera {
  highp   mat4 cc_matView;
  highp   mat4 cc_matViewInv;
  highp   mat4 cc_matProj;
  highp   mat4 cc_matProjInv;
  highp   mat4 cc_matViewProj;
  highp   mat4 cc_matViewProjInv;
  highp   vec4 cc_cameraPos;
  mediump vec4 cc_surfaceTransform;
  mediump vec4 cc_screenScale;
  mediump vec4 cc_exposure;
  mediump vec4 cc_mainLitDir;
  mediump vec4 cc_mainLitColor;
  mediump vec4 cc_ambientSky;
  mediump vec4 cc_ambientGround;
  mediump vec4 cc_fogColor;
  mediump vec4 cc_fogBase;
  mediump vec4 cc_fogAdd;
  mediump vec4 cc_nearFar;
  mediump vec4 cc_viewPort;
};
vec3 SRGBToLinear (vec3 gamma) {
#ifdef CC_USE_SURFACE_SHADER
  #if CC_USE_DEBUG_VIEW == CC_SURFACES_DEBUG_VIEW_COMPOSITE_AND_MISC && CC_SURFACES_ENABLE_DEBUG_VIEW
    if (!IS_DEBUG_VIEW_COMPOSITE_ENABLE_GAMMA_CORRECTION) {
      return gamma;
    }
  #endif
#endif
  return gamma * gamma;
}
vec4 CCFragOutput (vec4 color) {
  return color;
}
in vec2 v_uv;
in vec2 v_screen;
uniform sampler2D mainTexture;
layout(std140) uniform Constant {
  vec4 tint;
  vec4 fit;
};
vec4 frag () {
  float screenAspect = cc_screenSize.x / cc_screenSize.y;
  vec2 uv = vec2(v_screen.x, 1.0 - v_screen.y);
  vec2 scale = vec2(1.0);
  if (screenAspect > fit.z) scale.y = fit.z / screenAspect; else scale.x = screenAspect / fit.z;
  vec2 center = vec2(0.5, fit.y);
  uv = (uv - center) * scale / fit.x + center;
  vec4 c = texture(mainTexture, clamp(uv, 0.0, 1.0));
  c.rgb = SRGBToLinear(c.rgb);
  c *= tint;
  return CCFragOutput(c);
}
layout(location = 0) out vec4 cc_FragColor;
void main() { cc_FragColor = frag(); }

