    if (!IS_DEBUG_VIEW_COMPOSITE_ENABLE_GAMMA_CORRECTION) {
      return gamma;
    }
  #endif
#endif
  return gamma * gamma;
}
vec4 CCFragOutput (vec4 color) {
  return color;
}
varying vec2 v_uv;
varying vec2 v_screen;
uniform sampler2D mainTexture;
  uniform vec4 tint;
  uniform vec4 fit;
vec4 frag () {
  float screenAspect = cc_screenSize.x / cc_screenSize.y;
  vec2 uv = vec2(v_screen.x, 1.0 - v_screen.y);
